CREATE OR REPLACE FUNCTION public.staff_session_employee(p_token text)
 RETURNS employees
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'extensions', 'public', 'pg_temp'
AS $function$
